import Mathlib
open Topology

noncomputable def euclideanUtility (n : ℕ) (peak : EuclideanSpace ℝ (Fin n)) (y : EuclideanSpace ℝ (Fin n)) : ℝ :=
  -‖y - peak‖

def euclideanPreferredSet (n : ℕ) (y z : EuclideanSpace ℝ (Fin n)) : Set (EuclideanSpace ℝ (Fin n)) :=
  {x | ‖x - y‖ < ‖x - z‖}

import Mathlib
open Topology

variable {I X : Type*}

def IsDecisive (h : I) (socialPref : (I → X → X → Prop) → X → X → Prop) : Prop :=
  ∀ (P : I → X → X → Prop) (x y : X), P h x y → socialPref P x y

import Mathlib

def UPS {I : ℕ} {α : Type*} (X : Set α) (u : Fin I → α → ℝ) : Set (Fin I → ℝ) :=
  {v | ∃ x ∈ X, ∀ i, v i ≤ u i x}
